// src/pages/AIWrite.js

import { useState } from "react";

import {
  FiSearch,
  FiCamera,
} from "react-icons/fi";


function AIWrite() {

  // ==================================================
  // 책 검색
  // ==================================================

  const [searched, setSearched] =
    useState(false);

  const [selected, setSelected] =
    useState(false);


  // ==================================================
  // 선택한 책
  //
  // ★ 나중에 백엔드로 전달
  // ==================================================

  const [selectedBook, setSelectedBook] =
    useState(null);


  // ==================================================
  // 인상 깊은 구절
  //
  // 사용자가 직접 입력할 수도 있고
  // OCR 결과가 들어올 수도 있음
  // ==================================================

  const [quote, setQuote] =
    useState("");


  // ==================================================
  // OCR 결과
  //
  // ★ 사진에서 추출한 텍스트
  // ★ 백엔드로 전달할 데이터
  // ==================================================

  const [ocrText, setOcrText] =
    useState("");


  // ==================================================
  // 느낀점
  //
  // ★ 백엔드로 전달할 데이터
  // ==================================================

  const [thought, setThought] =
    useState("");


  // ==================================================
  // OCR 처리 상태
  // ==================================================

  const [ocrLoading, setOcrLoading] =
    useState(false);


  // ==================================================
  // AI 독후감 생성 상태
  // ==================================================

  const [generating, setGenerating] =
    useState(false);

  const [generated, setGenerated] =
    useState(false);


  // ==================================================
  // AI 독후감 결과
  // ==================================================

  const [aiReview, setAiReview] =
    useState("");


  // ==================================================
  // 책 선택
  // ==================================================

  const handleSelectBook = () => {

    const book = {
      title: "노르웨이의 숲",
      author: "무라카미 하루키",
    };

    setSelectedBook(book);

    setSelected(true);
  };


  // ==================================================
  // 📷 책 사진 → OCR
  //
  // ==================================================
  //
  // 현재 구조:
  //
  // 사용자
  //   ↓
  // 사진 촬영
  //   ↓
  // OCR API
  //   ↓
  // 텍스트 추출
  //   ↓
  // ocrText 저장
  //
  // ==================================================

  const handlePhotoOCR = async (event) => {

    const file =
      event.target.files?.[0];

    if (!file) {
      return;
    }


    setOcrLoading(true);


    try {

      // ==================================================
      // ★★★★★ 백엔드 OCR 연동 부분 ★★★★★
      // ==================================================
      //
      // 백엔드에서 OCR을 처리한다면
      // 아래 방식으로 이미지를 전달
      //
      // ==================================================

      /*
      const formData = new FormData();

      formData.append(
        "image",
        file
      );


      const response =
        await fetch(
          "http://localhost:8080/api/ocr",
          {
            method: "POST",

            body: formData,
          }
        );


      if (!response.ok) {
        throw new Error(
          "OCR 요청 실패"
        );
      }


      const data =
        await response.json();


      // 백엔드에서
      //
      // {
      //   "text": "추출된 문장"
      // }
      //
      // 형태로 반환한다고 가정

      setOcrText(
        data.text
      );


      // OCR 결과를
      // 인상 깊은 구절에도 표시

      setQuote(
        data.text
      );
      */


      // ==================================================
      // 현재 프론트 테스트용
      // ==================================================

      setTimeout(() => {

        const testText =
          "상실 이후에도 사람은 계속 살아간다.";

        setOcrText(
          testText
        );

        setQuote(
          testText
        );

        setOcrLoading(false);

      }, 700);


    } catch (error) {

      console.error(
        "OCR 처리 실패:",
        error
      );

      setOcrLoading(false);

    }

  };


  // ==================================================
  // ✨ AI 독후감 생성
  //
  // ★★★★★ 핵심 백엔드 연동 부분 ★★★★★
  //
  // 여기서
  //
  // 1. 책 정보
  // 2. OCR 텍스트
  // 3. 사용자가 작성한 느낀점
  //
  // 을 백엔드에 전달
  //
  // 백엔드는
  //
  // AI 독후감 생성
  //       ↓
  // DB 저장
  //       ↓
  // 생성된 독후감 반환
  //
  // ==================================================

  const handleGenerateReview =
    async () => {

      // 책을 선택하지 않았으면 생성하지 않음

      if (!selectedBook) {

        alert(
          "먼저 책을 선택해주세요."
        );

        return;
      }


      // 느낀점이 없는 경우

      if (!thought.trim()) {

        alert(
          "느낀점을 입력해주세요."
        );

        return;
      }


      setGenerating(true);


      // ==================================================
      // ★ 백엔드로 전달할 데이터
      // ==================================================

      const requestData = {

        // ----------------------------------------------
        // 책 정보
        // ----------------------------------------------

        book: {

          title:
            selectedBook.title,

          author:
            selectedBook.author,

        },


        // ----------------------------------------------
        // OCR로 추출한 구절
        // ----------------------------------------------

        ocrText:
          ocrText,


        // ----------------------------------------------
        // 사용자가 직접 입력한 구절
        //
        // OCR을 사용하지 않고 직접 입력할 수도 있으므로
        // 함께 전달
        // ----------------------------------------------

        quote:
          quote,


        // ----------------------------------------------
        // 사용자가 작성한 느낀점
        // ----------------------------------------------

        thought:
          thought,

      };


      console.log(
        "📤 백엔드로 보낼 독후감 데이터:",
        requestData
      );


      try {

        // ==================================================
        // ★★★★★ 실제 백엔드 연동 부분 ★★★★★
        // ==================================================
        //
        // 백엔드 API가 정해지면
        // 아래 주석을 풀면 됨.
        //
        // ==================================================

        /*
        const response =
          await fetch(
            "http://localhost:8080/api/reviews",
            {
              method: "POST",

              headers: {
                "Content-Type":
                  "application/json",
              },

              body:
                JSON.stringify(
                  requestData
                ),
            }
          );


        if (!response.ok) {

          throw new Error(
            "독후감 생성 요청 실패"
          );

        }


        const data =
          await response.json();


        // ==================================================
        // 백엔드 응답 예시
        //
        // {
        //   "reviewId": 123,
        //   "review":
        //     "AI가 생성한 독후감...",
        //   "saved": true
        // }
        // ==================================================


        setAiReview(
          data.review
        );


        setGenerated(true);

        */


        // ==================================================
        // 현재 프론트 테스트용
        // ==================================================

        setTimeout(() => {

          const result =
            `“${selectedBook.title}”은 상실과 외로움 속에서도 사람 사이의 연결이 얼마나 중요한지를 보여주는 작품이었다.

${thought}

특히 ${
            ocrText ||
            quote ||
            "인상 깊었던 구절"
          }이라는 문장을 통해 작품 속 인물들의 감정과 관계에 대해 다시 생각해볼 수 있었다.`;


          setAiReview(
            result
          );


          setGenerated(true);

          setGenerating(false);

        }, 800);


      } catch (error) {

        console.error(
          "독후감 생성 실패:",
          error
        );

        alert(
          "독후감 생성에 실패했습니다."
        );

        setGenerating(false);

      }

    };


  // ==================================================
  // 화면
  // ==================================================

  return (

    <div className="page">

      {/* ==================================================
          상단
      ================================================== */}

      <div className="top-bar">

        <div className="logo">
          READLY
        </div>

      </div>


      <div className="line"></div>


      {/* ==================================================
          제목
      ================================================== */}

      <div className="write-top">

        <div className="write-title">
          AI 독후감 작성
        </div>

        <div className="write-sub">
          책과 감상을 기록해보세요
        </div>

      </div>


      {/* ==================================================
          책 검색
      ================================================== */}

      <div className="write-card">

        <div className="input-label">
          어떤 책을 읽었나요?
        </div>


        <div className="book-search">

          <FiSearch />

          <input
            placeholder="책 제목 검색하기"

            onChange={() =>
              setSearched(true)
            }

          />

        </div>


        {/* ==================================================
            검색 결과
        ================================================== */}

        {searched && !selected && (

          <div
            className="search-item"

            onClick={
              handleSelectBook
            }

          >

            <div className="search-cover">
              📘
            </div>


            <div>

              <div className="book-name">
                노르웨이의 숲
              </div>

              <div className="book-author">
                무라카미 하루키
              </div>

            </div>

          </div>

        )}


        {/* ==================================================
            선택된 책
        ================================================== */}

        {selected &&
          selectedBook && (

            <div className="book-result">

              <div className="book-cover">
                📘
              </div>


              <div>

                <div className="book-name">
                  {selectedBook.title}
                </div>

                <div className="book-author">
                  {selectedBook.author}
                </div>

              </div>

            </div>

          )}

      </div>


      {/* ==================================================
          인상 깊은 구절
      ================================================== */}

      <div className="write-card">

        <div className="input-label">
          인상 깊은 구절
        </div>


        <textarea
          className="write-textarea"

          placeholder="기억에 남는 문장을 적어보세요"

          value={quote}

          onChange={(e) =>
            setQuote(
              e.target.value
            )
          }

        />


        {/* ==================================================
            📷 사진 촬영 → OCR
        ================================================== */}

        <label className="photo-btn">

          <FiCamera />

          {ocrLoading
            ? "문장을 읽고 있어요..."
            : "책 구절 사진 찍기"}


          <input

            type="file"

            accept="image/*"

            capture="environment"

            onChange={
              handlePhotoOCR
            }

            style={{
              display: "none",
            }}

          />

        </label>


        {/* ==================================================
            OCR 결과 표시
        ================================================== */}

        {ocrText && (

          <div
            style={{
              marginTop:
                "12px",

              padding:
                "12px",

              background:
                "#f7f9f1",

              borderRadius:
                "12px",

              color:
                "#666",

              fontSize:
                "13px",

              lineHeight:
                "1.5",
            }}
          >

            📖 사진에서 추출된 문장

            <br />

            {ocrText}

          </div>

        )}

      </div>


      {/* ==================================================
          느낀점
      ================================================== */}

      <div className="write-card">

        <div className="input-label">
          느낀점
        </div>


        <textarea
          className="write-textarea big"

          placeholder="책을 읽고 어떤 생각이 들었나요?"

          value={thought}

          onChange={(e) =>
            setThought(
              e.target.value
            )
          }

        />

      </div>


      {/* ==================================================
          AI 독후감 생성
      ================================================== */}

      <button
        className="generate-btn"

        onClick={
          handleGenerateReview
        }

        disabled={
          generating
        }

      >

        {generating
          ? "AI가 독후감을 작성하고 있어요..."
          : "AI 독후감 생성하기"}

      </button>


      {/* ==================================================
          AI 독후감 결과
      ================================================== */}

      {generated && (

        <div className="result-card">

          <div className="result-title">
            ✨ AI 독후감
          </div>


          <div className="result-content">
            {aiReview}
          </div>

        </div>

      )}

    </div>

  );
}


export default AIWrite;
